OM_uint32 process_spnego_continuation(OM_uint32 *minstat,
                                      gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 major_status, minor_status;
    gss_OID mech_type;
    OM_uint32 flags;
    gss_cred_id_t cred_handle = GSS_C_NO_CREDENTIAL;

    *minstat = 0;

    if (buf == GSS_C_NO_BUFFER) {
        return GSS_S_BAD_TOKEN;
    }

    // Verify token header
    if (memcmp(buf->value, "Negotiate", 9) != 0) {
        return GSS_S_BAD_SIG;
    }

    // Check for valid context
    if (*ctx != GSS_C_NO_CONTEXT) {
        // Continue context setup
        major_status = gss_continue_init(0, 0, cred_handle, mech_type, 0, ctx, &flags, responseToken, &minor_status);
        if (major_status != GSS_S_CONTINUE_NEEDED && major_status != GSS_S_COMPLETE) {
            return major_status;
        }
    } else {
        // Start new context
        major_status = gss_init_sec_context(&minor_status, cred_handle, ctx, NULL, mech_type, 0, 0, NULL, NULL, NULL, responseToken, NULL, NULL);
        if (major_status != GSS_S_CONTINUE_NEEDED && major_status != GSS_S_COMPLETE) {
            return major_status;
        }
    }

    // Process negotiation response
    if (major_status == GSS_S_COMPLETE) {
        *negState = COMPLETED;
        *return_token = SEND_TOKEN;
    } else if (major_status == GSS_S_CONTINUE_NEEDED) {
        *negState = CONTINUE;
        *return_token = SEND_TOKEN;
    } else {
        return GSS_S_FAILURE;
    }

    return major_status;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat,
                                      gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 status = GSS_S_COMPLETE;
    gss_OID mech_type = GSS_C_NULL_OID;
    OM_uint32 temp_minor_status = 0;
    gss_ctx_id_t mech_context = GSS_C_NO_CONTEXT;
    send_token_flag send_flag = GSS_C_NO_TOKEN;

    if (buf->length == 0 || buf->value == NULL) {
        *minstat = GSS_S_BAD_SIG;
        return GSS_S_FAILURE;
    }

    if (ctx == NULL || *ctx == GSS_C_NO_CONTEXT) {
        *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_FAILURE;
    }

    status = gss_get_mech_from_spnego_token(minstat, buf, &mech_type);
    if (status != GSS_S_COMPLETE) {
        return status;
    }

    status = gss_accept_sec_context(minstat,
                                    ctx,
                                    GSS_C_NO_CREDENTIAL,
                                    buf,
                                    GSS_C_NO_CHANNEL_BINDINGS,
                                    NULL,
                                    NULL,
                                    &mech_context,
                                    NULL,
                                    NULL,
                                    NULL);
    if (status != GSS_S_COMPLETE && status != GSS_S_CONTINUE_NEEDED) {
        *minstat = *minstat;
        return status;
    }

    if (status == GSS_S_CONTINUE_NEEDED) {
        send_flag = GSS_C_TOKEN_CONTINUE;
    } else {
        send_flag = GSS_C_TOKEN_FINAL;
    }

    if (responseToken != NULL) {
        responseToken->length = 0;
        responseToken->value = NULL;
    }

    if (mechListMIC != NULL) {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    *negState = (status == GSS_S_CONTINUE_NEEDED) ? NEG_STATE_CONTINUE : NEG_STATE_ESTABLISHED;
    *return_token = send_flag;

    return status;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf, gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken, gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState, send_token_flag *return_token) {
    OM_uint32 status = GSS_S_BAD_SIG;
    gss_OID mech = GSS_C_NULL_OID;
    OM_uint32 major_status, minor_status;
    gss_buffer_desc token = {0, 0};
    gss_OID_set_desc mech_set = {0, NULL};

    if (!buf || !buf->length || !buf->value) {
        if (minstat) *minstat = GSS_S_FAILURE;
        return GSS_S_BAD_BINDINGS;
    }

    token.length = buf->length;
    token.value = buf->value;

    if (verify_token_header(&token) != 0) {
        if (minstat) *minstat = GSS_S_FAILURE;
        return GSS_S_DEFECTIVE_TOKEN;
    }

    if (!ctx || *ctx == GSS_C_NO_CONTEXT) {
        if (minstat) *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_NO_CONTEXT;
    }

    if (gss_get_mechanism_list(&minor_status, &mech_set) != GSS_S_COMPLETE) {
        if (minstat) *minstat = minor_status;
        return GSS_S_FAILURE;
    }

    if (negotiate_mechanism(&major_status, &minor_status, mech_set, ctx, &token, &mech) != 0) {
        if (minstat) *minstat = minor_status;
        gss_release_oid_set(&minor_status, &mech_set);
        return major_status;
    }

    if (mech != GSS_C_NULL_OID) {
        process_negotiation_response(&major_status, &minor_status, mech, ctx, &token,
                                     responseToken, mechListMIC, negState, return_token);
    }

    gss_release_oid_set(&minor_status, &mech_set);
    if (major_status != GSS_S_COMPLETE) {
        if (minstat) *minstat = minor_status;
        return major_status;
    }

    if (minstat) *minstat = 0;
    return GSS_S_COMPLETE;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint33 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 status = 0;
    OM_uint32 major_status, minor_status;
    gss_OID mech_type = GSS_C_NULL_OID;
    gss_buffer_desc output_token = GSS_C_EMPTY_BUFFER;

    *minstat = 0;

    if (buf == NULL || buf->length <= 0) {
        *minstat = GSS_S_BAD_SIG;
        return GSS_S_FAILURE;
    }

    // Verify token header and context
    if (ctx == NULL || *ctx == GSS_C_NO_CONTEXT) {
        *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_FAILURE;
    }

    // Process the token
    major_status = gss_unwrap(&minor_status, *ctx, buf, &output_token,
                              NULL, NULL, NULL);

    if (major_status != GSS_S_COMPLETE) {
        *minstat = GSS_S_DEFECTIVE_TOKEN;
        return GSS_S_FAILURE;
    }

    // Determine the mechanism and update the state
    major_status = gss_inquire_context(&minor_status, *ctx, NULL, &mech_type,
                                       NULL, NULL, NULL, NULL, NULL);

    if (major_status != GSS_S_COMPLETE) {
        *minstat = GSS_S_FAILURE;
        return GSS_S_FAILURE;
    }

    // Copy the output token to the responseToken
    if (responseToken != NULL) {
        responseToken->length = output_token.length;
        responseToken->value = output_token.value;
    }

    // Mechanism List MIC
    if (mechListMIC != NULL) {
        gss_wrap(&minor_status, *ctx, 0, NULL, &mechListMIC);
    }

    // Update negotiation state and return token flags
    *negState = NEG_STATE_ESTABLISHED;
    *return_token = SEND_TOKEN_FLAG;

    return status;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint33 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 status = 0;
    OM_uint32 major_status, minor_status;

    /* Validate the token header */
    if (buf->length < GSS_SPNEGO_HEADER_SIZE || memcmp(buf->value, GSS_SPNEGO_OID, GSS_SPNEGO_OID_SIZE) != 0) {
        *minstat = GSS_S_BAD_SIG;
        return GSS_S_FAILURE;
    }

    /* Check if the context is valid */
    if (!ctx || *ctx == GSS_C_NO_CONTEXT) {
        *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_FAILURE;
    }

    /* Process the negotiation response */
    status = gss_process_context_token(&minor_status, *ctx, buf, responseToken, &negState);

    if (status != GSS_S_COMPLETE) {
        *minstat = minor_status;
        return status;
    }

    /* Update the negotiation state */
    if (*negState != GSS_NEG_STATE_ESTABLISHED) {
        if (mechListMIC->length > 0) {
            memcpy(mechListMIC->value, buf->value + GSS_SPNEGO_HEADER_SIZE,
                   mechListMIC->length);
        }
    }

    /* Manage memory for the supported mechanism */
    if (return_token) {
        *return_token = SEND_TOKEN_FLAG_SEND;
    }

    return GSS_S_COMPLETE;
}
